import sys
import os
import random
import string

def generate_token():
    """Generate a random token using only letters and digits."""
    length = 16
    characters = string.ascii_letters + string.digits
    return ''.join(random.choice(characters) for _ in range(length))

def load_tokens():
    """Load tokens from the persistent store file."""
    file_path = "tokens.txt"
    tokens = []
    if os.path.exists(file_path):
        with open(file_path, 'r') as file:
            for line in file:
                line = line.strip()
                if line:
                    token, user_id = line.split(' ', 1)
                    tokens.append((token, user_id))
    return tokens

def save_tokens(tokens):
    """Save tokens to the persistent store file in order."""
    file_path = "tokens.txt"
    with open(file_path, 'w') as file:
        for token, user_id in tokens:
            file.write(f"{token} {user_id}\n")

def issue(user_id):
    """Issue a new token for the given user_id."""
    tokens = load_tokens()
    token = generate_token()

    # Ensure the token is unique
    while any(t[0] == token for t in tokens):
        token = generate_token()

    # Add the new token to the list
    new_tokens = tokens + [(token, user_id)]
    save_tokens(new_tokens)

    print(token)

def validate(token):
    """Validate a token and print the result."""
    tokens = load_tokens()
    for t, user_id in tokens:
        if t == token:
            print(f"VALID {user_id}")
            return
    print("INVALID")

def list_tokens():
    """List all stored tokens in order of issuance."""
    tokens = load_tokens()
    for token, user_id in tokens:
        print(f"{token} {user_id}")

def main():
    if len(sys.argv) < 3:
        print("Usage: python token_manager.py <command> <args>")
        print("Commands: issue <user_id>, validate <token>, list")
        sys.exit(1)

    command = sys.argv[1]

    if command == "issue":
        if len(sys.argv) != 3:
            print("Usage: python token_manager.py issue <user_id>")
            sys.exit(1)
        issue(sys.argv[2])

    elif command == "validate":
        if len(sys.argv) != 3:
            print("Usage: python token_manager.py validate <token>")
            sys.exit(1)
        validate(sys.argv[2])

    elif command == "list":
        list_tokens()

    else:
        print("Unknown command. Use 'issue', 'validate', or 'list'.")
        sys.exit(1)

if __name__ == "__main__":
    main()

