import json
import sys
import requests
import os
from typing import Dict, Any, List

def load_config(config_path: str) -> Dict[str, Any]:
    with open(config_path, 'r') as f:
        return json.load(f)

def fetch_metric(url: str) -> float:
    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
        data = response.json()
        if not isinstance(data, dict) or "metric" not in data:
            raise ValueError("Invalid response format")
        return float(data["metric"])
    except Exception as e:
        raise RuntimeError(f"Failed to fetch metric from {url}: {str(e)}")

def save_cache(cache_file: str, name_to_metric: Dict[str, float], mean: float):
    cache_data = {
        "name_to_metric": name_to_metric,
        "mean": mean
    }
    with open(cache_file, 'wb') as f:
        f.write(json.dumps(cache_data).encode('utf-8'))

def load_cache(cache_file: str) -> Dict[str, Any]:
    if not os.path.exists(cache_file):
        return None
    with open(cache_file, 'rb') as f:
        data = f.read().decode('utf-8')
        return json.loads(data)
    return None

def main():
    if len(sys.argv) < 2:
        print("Usage: python remote_summary.py <config_file> [--offline]")
        sys.exit(1)

    config_path = sys.argv[1]
    offline_flag = '--offline' in sys.argv

    config = load_config(config_path)
    sources = config.get("sources", [])
    cache_file = config.get("cache_file", "./cache.bin")

    if offline_flag:
        cached_data = load_cache(cache_file)
        if cached_data is None:
            print("no cache available", file=sys.stderr)
            sys.exit(1)

        name_to_metric = cached_data["name_to_metric"]
        mean = cached_data["mean"]

        for source in sources:
            name = source["name"]
            if name in name_to_metric:
                print(f"{name}: {name_to_metric[name]}")
        print(f"mean: {mean}")
    else:
        name_to_metric = {}
        for source in sources:
            name = source["name"]
            url = source["url"]
            try:
                metric = fetch_metric(url)
                name_to_metric[name] = metric
            except Exception as e:
                print(f"Error fetching {url}: {str(e)}", file=sys.stderr)

        mean = sum(name_to_metric.values()) / len(name_to_metric) if name_to_metric else 0.0

        # Save to cache
        save_cache(cache_file, name_to_metric, mean)

        # Print results
        for source in sources:
            name = source["name"]
            print(f"{name}: {name_to_metric[name]}")
        print(f"mean: {mean}")

if __name__ == "__main__":
    main()

