import sys
import json
import os

def main():
    if len(sys.argv) != 2:
        print("ERROR: unknown operation")
        sys.exit(1)

    operation_name = sys.argv[1]

    # Read input from stdin
    try:
        input_line = sys.stdin.readline().strip()
        if not input_line:
            print("ERROR: invalid token")
            sys.exit(1)
        input_data = json.loads(input_line)
    except json.JSONDecodeError:
        print("ERROR: invalid token")
        sys.exit(1)

    # Read token from environment
    token_str = os.getenv("APP_TOKEN")
    if not token_str:
        print("ERROR: invalid token")
        sys.exit(1)

    try:
        token_data = json.loads(token_str)
    except json.JSONDecodeError:
        print("ERROR: invalid token")
        sys.exit(1)

    if "user" not in token_data or "roles" not in token_data:
        print("ERROR: invalid token")
        sys.exit(1)

    user = token_data["user"]
    roles = token_data["roles"]

    # Define operations
    OPERATIONS = [
        {
            "name": "sum",
            "required_role": "math",
            "expression": "x + y",
        },
        {
            "name": "greet",
            "required_role": "reports",
            "expression": "f'Hello, {user}! You sent {msg}.'",
        },
    ]

    # Find operation by name
    operation = next((op for op in OPERATIONS if op["name"] == operation_name), None)
    if not operation:
        print("ERROR: unknown operation")
        sys.exit(1)

    # Check role authorization
    if operation["required_role"] not in roles:
        print("ERROR: forbidden")
        sys.exit(1)

    # Evaluate expression with available variables
    try:
        # Create a safe namespace for evaluation
        namespace = input_data.copy()
        namespace["user"] = user
        result = eval(operation["expression"], {}, namespace)
    except Exception as e:
        print("ERROR: invalid operation")
        sys.exit(1)

    # Format and output result
    output = {
        "operation": operation_name,
        "user": user,
        "result": result
    }
    print(json.dumps(output))

