import hashlib
import re

def evaluate_condition(condition_str, run_level):
    try:
        # Replace RUN_LEVEL with the actual value
        condition_with_run_level = condition_str.replace('RUN_LEVEL', str(run_level))
        # Evaluate the expression safely
        result = eval(condition_with_run_level)
        return result
    except Exception:
        return 0

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    config_path = sys.argv[1]

    try:
        with open(config_path, 'r', encoding='utf-8') as file:
            for line in file:
                line = line.strip()
                if not line or line.startswith('#'):
                    continue

                fields = line.split('\t')
                if len(fields) != 3:
                    continue

                command, condition, expected_digest = fields
                command = command.strip()
                condition = condition.strip()
                expected_digest = expected_digest.strip()

                run_level = int(os.getenv('RUN_LEVEL', '0'))

                condition_result = evaluate_condition(condition, run_level)

                if condition_result == 0:
                    print(f"SKIP\t{command}")
                else:
                    try:
                        # Run the command and capture output
                        result = subprocess.run(
                            command,
                            shell=True,
                            capture_output=True,
                            text=False,
                            timeout=30
                        )

                        if result.returncode != 0:
                            print(f"MISMATCH\t{command}")
                        else:
