import sys
import re
import xml.etree.ElementTree as ET

def parse_xml_config(xml_path):
    with open(xml_path, 'r', encoding='utf-8') as file:
        content = file.read()

    root = ET.fromstring(content)
    variables = {}
    for var in root.findall('variable'):
        name = var.get('name')
        value_str = var.get('value')
        if value_str is not None:
            try:
                value = float(value_str)
                variables[name] = value
            except ValueError:
                pass
    return variables

def evaluate_expression(expr, variables):
    try:
        # Replace variable names in the expression with their values
        for var_name, var_value in variables.items():
            expr = expr.replace(f'{{{{{{{var_name}}}}}}}}', str(var_value))

        # Evaluate the arithmetic expression
        result = eval(expr)
        return str(result)
    except Exception as e:
        return str(e)

def process_template(template_text, variables):
    # Find all {{EXPR}} placeholders
    pattern = r'\{\{([^{}]*)\}\}'
    def replace_match(match):
        expr = match.group(1)
        try:
            # Evaluate the expression using the variables
            result = evaluate_expression(expr, variables)
            return result
        except:
            return expr  # fallback if evaluation fails

    return re.sub(pattern, replace_match, template_text)

def main():
    print("Enter config XML path: ", end="")
    config_path = input().strip()

    print("Enter template path: ", end="")
    template_path = input().strip()

    print("Enter output path: ", end="")
    output_path = input().strip()

    # Parse XML configuration
    variables = parse_xml_config(config_path)

    # Read template file
    with open(template_path, 'r', encoding='utf-8') as file:
        template_content = file.read()

    # Process template with variables
    processed_content = process_template(template_content, variables)

    # Write result to output file
    with open(output_path, 'w', encoding='utf-8') as file:
        file.write(processed_content)

if __name__ == "__main__":
