        with open(workload_path, 'r') as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue

                parts = line.split()
                if len(parts) != 3 or parts[0] != 'ALLOCATE':
                    print(f"Invalid instruction format: {line}")
                    continue

                user_id = parts[1]
                requested = int(parts[2])

                # Track current allocations per user
                allocations = {}
                total_allocated = 0

                # Check if allocation is possible
                if total_allocated + requested > max_total_bytes:
                    print(f"THROTTLED {user_id} {requested}")
                else:
                    # Accept allocation
                    if user_id in allocations:
                        allocations[user_id] += requested
                    else:
                        allocations[user_id] = requested
                    total_allocated += requested
                    print(f"ALLOCATED {user_id} {requested}")

    except FileNotFoundError:
        print(f"Workload file not found: {workload_path}")
        sys.exit(1)
    except Exception as e:
