import sys
import json
import requests
from xml.etree import ElementTree as ET
from urllib.parse import urlparse

def parse_config(xml_path):
    try:
        with open(xml_path, 'r', encoding='utf-8') as file:
            content = file.read()
    except FileNotFoundError:
        sys.exit(f"Configuration file {xml_path} not found.")

    try:
        root = ET.fromstring(content)
    except ET.ParseError as e:
        sys.exit(f"Error parsing XML configuration: {e}")

    feeds = []
    for feed_elem in root.findall('feed'):
        url = feed_elem.get('url')
        name = feed_elem.get('name')
        if not url:
            sys.exit("Missing 'url' attribute in feed element.")
        if not name:
            name = url
        feeds.append({'url': url, 'name': name})
    return feeds

def fetch_feed_titles(feeds):
    result = {}
    for feed in feeds:
        url = feed['url']
        name = feed['name']
        try:
            response = requests.get(url, timeout=10)
            if response.status_code == 200 and response.content:
                try:
                    root = ET.fromstring(response.content)
                    titles = []
                    for item in root.findall('.//item'):
                        title_elem = item.find('title')
                        if title_elem is not None:
                            titles.append(title_elem.text if title_elem.text else "")
                    result[name] = titles
                except ET.ParseError:
                    result[name] = []
            else:
                result[name] = []
        except requests.RequestException:
            result[name] = []
    return result

def main():
    if len(sys.argv) != 2:
        sys.exit("Usage: python fetch_feed_titles.py path/to/config.xml")

    config_path = sys.argv[1]
    feeds = parse_config(config_path)
    titles_data = fetch_feed_titles(feeds)
    print(json.dumps(titles_data, indent=2))

if __name__ == "__main__":
    main()

import sys
import json
import os

def login_mode():
    line = sys.stdin.readline().strip()
    if not line:
        print(json.dumps({"error": "invalid_credentials"}))
        return

    try:
        data = json.loads(line)
        accounts = data.get("accounts", [])
        username = sys.stdin.readline().strip()
        password = sys.stdin.readline().strip()

        if not username or not password:
            print(json.dumps({"error": "invalid_credentials"}))
            return

        matched = False
        for account in accounts:
            if account.get("username") == username and account.get("password") == password:
                matched = True
                break

        if not matched:
            print(json.dumps({"error": "invalid_credentials"}))
            return

        # Generate a non-empty token
        token = "token_" + username + "_" + str(hash(username + password)) % 1000000
        result = {
            "username": username,
            "token": token
        }
        print(json.dumps(result))

    except Exception:
        print(json.dumps({"error": "invalid_credentials"}))

def page_mode():
    try:
        first_line = sys.stdin.readline().strip()
        second_line = sys.stdin.readline().strip()

        if not first_line or not second_line:
            print("NO ACCESS")
            return

        sessions_data = json.loads(first_line)
        token_data = json.loads(second_line)

        sessions = sessions_data.get("sessions", [])
        provided_token = token_data.get("token")

        if not provided_token:
            print("NO ACCESS")
            return

        matched = False
        for session in sessions:
            if session.get("token") == provided_token:
                matched = True
                username = session.get("username")
                token = provided_token
                break

        if not matched:
            print("NO ACCESS")
            return

        # Read profile_template.html
        template_path = "profile_template.html"
        if not os.path.exists(template_path):
            print("NO ACCESS")
            return

        with open(template_path, 'r') as f:
            template = f.read()

        # Replace placeholders
        html = template.replace("{{username}}", username).replace("{{token}}", token)
        print(html)

    except Exception:
        print("NO ACCESS")

if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit(1)

    mode = sys.argv[1]
    if mode == "login":
        login_mode()
    elif mode == "page":
        page_mode()
