import sys
import xml.etree.ElementTree as ET
import pickle
import os

def parse_resources(xml_path):
    tree = ET.parse(xml_path)
    root = tree.getroot()
    resources = {}
    for resource_elem in root.findall('resource'):
        name = resource_elem.get('name')
        max_concurrent = int(resource_elem.get('max_concurrent'))
        resources[name] = max_concurrent
    return resources

def load_state(state_path):
    if not os.path.exists(state_path) or os.path.getsize(state_path) == 0:
        return {name: {'running': [], 'queued': []} for name in resources}
    with open(state_path, 'rb') as f:
        return pickle.load(f)

def save_state(state, state_path):
    with open(state_path, 'wb') as f:
        pickle.dump(state, f)

def main():
    if len(sys.argv) != 3:
        sys.stderr.write("Usage: python scheduler.py resources.xml state.bin\n")
        sys.exit(1)

    xml_path = sys.argv[1]
    state_path = sys.argv[2]

    # Parse resources from XML
    try:
        resources = parse_resources(xml_path)
    except ET.ParseError as e:
        sys.stderr.write(f"Error parsing XML: {e}\n")
        sys.exit(1)

    # Load state from file
    state = load_state(state_path)

    # Process input lines from stdin
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) != 2:
            continue
        resource_name = parts[0]
        job_id = parts[1]

        # Validate resource name
        if resource_name not in resources:
            continue

        max_concurrent = resources[resource_name]
        running_count = len(state[resource_name]['running'])

        if running_count < max_concurrent:
            # Job starts
            state[resource_name]['running'].append(job_id)
            print(f"start {job_id} on {resource_name}")
        else:
            # Job queues
            state[resource_name]['queued'].append(job_id)
            print(f"queue {job_id} on {resource_name}")

    # Save updated state
    save_state(state, state_path)

