import xml.etree.ElementTree as ET
import hashlib

def compute_digest(secret_key, token):
    """Compute a deterministic digest from secret key and token."""
    return hashlib.md5((secret_key + token).encode()).hexdigest()

def main():
    if len(sys.argv) != 4:
        sys.exit(1)

