            if name and value:
                variables[name] = float(value)

    return per_user_max, variables

def evaluate_expression(expr, variables):
    try:
        # Replace variable names in the expression with their values
        # We use a simple substitution for now, but we need to handle expressions safely
        # We'll use eval with a restricted namespace
        safe_globals = {
            'abs': abs,
            'int': int,
            'float': float,
            'round': round,
            'pow': pow,
            'operator': operator,
            '+': operator.add,
            '-': operator.sub,
            '*': operator.mul,
            '/': operator.truediv,
            '**': operator.pow,
        }
        safe_globals.update(variables)

        # Parse the expression to ensure it's valid
        node = ast.parse(expr, mode='eval')

        # Evaluate the expression in a safe environment
        result = eval(compile(node, '<string>', 'eval'), safe_globals, safe_globals)

        return result
    except Exception as e:
        return None

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    xml_path = sys.argv[1]
    per_user_max, variables = parse_xml_config(xml_path)

    user_eval_count = {}

    try:
        for line in sys.stdin:
            line = line.strip()
            if not line:
                continue

            parts = line.split(':', 1)
            if len(parts) != 2:
                continue

            user_id = parts[0].strip()
            expression = parts[1].strip()

            if user_id == '':
                continue

            if user_id in user_eval_count and user_eval_count[user_id] >= per_user_max:
                print(f"THROTTLED {user_id}")
                continue

            result = evaluate_expression(expression, variables)
            if result is None:
                print(f"ERROR {user_id}")
            else:
                user_eval_count[user_id] = user_eval_count.get(user_id, 0) + 1
                print(f"{user_id}: {result}")

    except Exception as e:
        sys.exit(1)

if __name__ == "__main__":
    main()
